import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # dp[i][j] = max score for subarray a[i..j]
    dp = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = a[i]
            else:
                best = 0
                for k in range(i, j):
                    left = dp[i][k]
                    right = dp[k+1][j]
                    # merge cost: if both sides have same value, gain that value
                    # We need to know the resulting value of each segment.
                    # Since we only track max score, we need more info.
                    pass

    # The above approach is insufficient. Let's use interval DP with value tracking.
    # dp[i][j] = (max_score, resulting_value) but resulting value may vary.
    # Actually, the resulting value of merging a segment is determined by the process.
    # Let's think: merging two segments of values x and y gives value x+1 if x==y, else max(x,y)?
    # No, the problem says: choose two adjacent with same value, replace with value+1.
    # So we can only merge equal values. The resulting value is that value+1.
    # This is like 2048 merging.
    # We need to find max possible value achievable from the whole array.
    # This is a known problem: interval DP where dp[i][j] = value if a[i..j] can be merged into a single number, else -1.

    dp2 = [[-1] * n for _ in range(n)]
    for i in range(n):
        dp2[i][i] = a[i]

    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1
            for k in range(i, j):
                if dp2[i][k] != -1 and dp2[i][k] == dp2[k+1][j]:
                    dp2[i][j] = max(dp2[i][j], dp2[i][k] + 1)

    # Now we need max value over all possible partitions into mergeable segments.
    # dp3[i] = max value achievable from prefix a[0..i-1]
    dp3 = [0] * (n + 1)
    for i in range(1, n + 1):
        dp3[i] = dp3[i-1]  # a[i-1] alone
        for k in range(i):
            if dp2[k][i-1] != -1:
                dp3[i] = max(dp3[i], max(dp3[k], dp2[k][i-1]))

    print(dp3[n])

if __name__ == "__main__":
    solve()

